package config

import (
	"github.com/BurntSushi/toml"
)

// Global holds mesh-wide tuning parameters.
type Global struct {
	HealthIntervalMs        int `toml:"health_interval_ms"`
	UnhealthyThreshold      int `toml:"unhealthy_threshold"`
	HealthyThreshold        int `toml:"healthy_threshold"`
	StatsWindowSec          int `toml:"stats_window_sec"`
	CircuitBreakerThreshold int `toml:"circuit_breaker_threshold"`
	CircuitBreakerTimeoutMs int `toml:"circuit_breaker_timeout_ms"`
}

// Endpoint describes one backend endpoint from config.
type Endpoint struct {
	Address     string `toml:"address"`
	Weight      int    `toml:"weight"`
	HealthCheck string `toml:"health_check"`
	HealthPath  string `toml:"health_path"`
	HealthCmd   string `toml:"health_cmd"`
}

// Service describes one routed service from config.
type Service struct {
	Name                    string     `toml:"name"`
	ListenPort             int        `toml:"listen_port"`
	RoutingMode             string     `toml:"routing_mode"`
	DrainTimeoutMs          int        `toml:"drain_timeout_ms"`
	MaxConnectionsPerEndpoint int      `toml:"max_connections_per_endpoint"`
	Endpoints               []Endpoint `toml:"endpoint"`
}

// Config is the parsed application configuration.
type Config struct {
	Global   Global
	Services []Service
}

// Load reads and normalizes a TOML config file.
func Load(path string) (*Config, error) {
	var cfg Config
	if _, err := toml.DecodeFile(path, &cfg); err != nil {
		return nil, err
	}
	if cfg.Global.HealthIntervalMs <= 0 {
		cfg.Global.HealthIntervalMs = 2000
	}
	if cfg.Global.UnhealthyThreshold <= 0 {
		cfg.Global.UnhealthyThreshold = 3
	}
	if cfg.Global.HealthyThreshold <= 0 {
		cfg.Global.HealthyThreshold = 2
	}
	if cfg.Global.StatsWindowSec <= 0 {
		cfg.Global.StatsWindowSec = 60
	}
	if cfg.Global.CircuitBreakerThreshold <= 0 {
		cfg.Global.CircuitBreakerThreshold = 3
	}
	if cfg.Global.CircuitBreakerTimeoutMs <= 0 {
		cfg.Global.CircuitBreakerTimeoutMs = 5000
	}
	for i := range cfg.Services {
		s := &cfg.Services[i]
		if s.RoutingMode == "" {
			s.RoutingMode = "weighted-round-robin"
		}
		if s.DrainTimeoutMs <= 0 {
			s.DrainTimeoutMs = 5000
		}
		if s.MaxConnectionsPerEndpoint <= 0 {
			s.MaxConnectionsPerEndpoint = 100
		}
		for j := range s.Endpoints {
			ep := &s.Endpoints[j]
			if ep.HealthCheck == "" {
				ep.HealthCheck = "tcp"
			}
			if ep.Weight < 0 {
				ep.Weight = 0
			}
		}
	}
	return &cfg, nil
}
EOF

cat > internal/stats/stats.go <<'EOF'
package stats

import (
	"sync"
	"time"
)

type entry struct {
	timestamp time.Time
	bytesIn   int64
	bytesOut  int64
	latency   time.Duration
	err       bool
}

// Collector keeps rolling connection statistics for one endpoint.
type Collector struct {
	mu         sync.Mutex
	window     time.Duration
	entries    []entry
	rejections []time.Time
}

// New creates a collector with the given window length.
func New(window time.Duration) *Collector {
	if window <= 0 {
		window = time.Minute
	}
	return &Collector{window: window}
}

// RecordConnection records a finished connection attempt.
func (c *Collector) RecordConnection(bytesIn, bytesOut int64, latency time.Duration, err bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	now := time.Now()
	c.entries = append(c.entries, entry{timestamp: now, bytesIn: bytesIn, bytesOut: bytesOut, latency: latency, err: err})
	c.trim(now)
}

// RecordRejection records a rejected connection because the endpoint was at capacity.
func (c *Collector) RecordRejection() {
	c.mu.Lock()
	defer c.mu.Unlock()
	now := time.Now()
	c.rejections = append(c.rejections, now)
	c.trim(now)
}

func (c *Collector) trim(now time.Time) {
	cutoff := now.Add(-c.window)
	i := 0
	for i < len(c.entries) && c.entries[i].timestamp.Before(cutoff) {
		i++
	}
	if i > 0 {
		c.entries = c.entries[i:]
	}
	j := 0
	for j < len(c.rejections) && c.rejections[j].Before(cutoff) {
		j++
	}
	if j > 0 {
		c.rejections = c.rejections[j:]
	}
}

// Snapshot returns current windowed stats. active is supplied by the state manager.
func (c *Collector) Snapshot(active int) Snapshot {
	c.mu.Lock()
	defer c.mu.Unlock()
	now := time.Now()
	cutoff := now.Add(-c.window)
	var total int
	var bytesIn, bytesOut int64
	var latencySum time.Duration
	var errors int
	for _, e := range c.entries {
		if e.timestamp.After(cutoff) || e.timestamp.Equal(cutoff) {
			total++
			bytesIn += e.bytesIn
			bytesOut += e.bytesOut
			latencySum += e.latency
			if e.err {
				errors++
			}
		}
	}
	rejected := 0
	for _, t := range c.rejections {
		if t.After(cutoff) || t.Equal(cutoff) {
			rejected++
		}
	}
	var avg float64
	if total > 0 {
		avg = float64(latencySum.Milliseconds()) / float64(total)
	}
	return Snapshot{
		TotalConnections:    total,
		ActiveConnections:   active,
		BytesIn:             bytesIn,
		BytesOut:            bytesOut,
		AvgLatencyMs:        avg,
		Errors:              errors,
		RejectedConnections: rejected,
	}
}

// Snapshot is a JSON-friendly stats view.
type Snapshot struct {
	TotalConnections    int     `json:"total_connections"`
	ActiveConnections   int     `json:"active_connections"`
	BytesIn             int64   `json:"bytes_in"`
	BytesOut            int64   `json:"bytes_out"`
	AvgLatencyMs        float64 `json:"avg_latency_ms"`
	Errors              int     `json:"errors"`
	RejectedConnections int     `json:"rejected_connections"`
}
EOF

cat > internal/circuit/breaker.go <<'EOF'
package circuit

import (
	"sync"
	"time"
)

type State string

const (
	Closed   State = "closed"
	Open     State = "open"
	HalfOpen State = "half_open"
)

// Breaker implements an endpoint circuit breaker.
type Breaker struct {
	mu                 sync.Mutex
	state              State
	consecutiveFailures int
	stateChangedAt     time.Time
	openedAt           time.Time
	timeout            time.Duration
	probeActive        bool
}

// New creates a closed breaker with the given open timeout.
func New(timeout time.Duration) *Breaker {
	now := time.Now()
	return &Breaker{
		state:          Closed,
		stateChangedAt: now,
		openedAt:       now,
		timeout:        timeout,
	}
}

// State returns the current state.
func (b *Breaker) State() State {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.state
}

// IsClosed returns true if the breaker is closed.
func (b *Breaker) IsClosed() bool {
	return b.State() == Closed
}

// IsOpen returns true if the breaker is open.
func (b *Breaker) IsOpen() bool {
	return b.State() == Open
}

// IsHalfOpen returns true if the breaker is half-open.
func (b *Breaker) IsHalfOpen() bool {
	return b.State() == HalfOpen
}

// Open forces the breaker open and restarts the timeout clock.
func (b *Breaker) Open() {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := time.Now()
	b.state = Open
	b.stateChangedAt = now
	b.openedAt = now
	b.consecutiveFailures++
	b.probeActive = false
}

// MaybeHalfOpen transitions from open to half_open if the timeout has elapsed.
func (b *Breaker) MaybeHalfOpen() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.state == Open && time.Since(b.openedAt) >= b.timeout {
		b.state = HalfOpen
		b.stateChangedAt = time.Now()
		b.probeActive = false
		return true
	}
	return false
}

// AcquireProbe attempts to take the single allowed half-open probe connection.
func (b *Breaker) AcquireProbe() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.state == HalfOpen && !b.probeActive {
		b.probeActive = true
		return true
	}
	return false
}

// ProbeSuccess closes the circuit and clears failure counts.
func (b *Breaker) ProbeSuccess() {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := time.Now()
	b.state = Closed
	b.stateChangedAt = now
	b.consecutiveFailures = 0
	b.probeActive = false
}

// ProbeFailure reopens the circuit and restarts the timeout.
func (b *Breaker) ProbeFailure() {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := time.Now()
	b.state = Open
	b.stateChangedAt = now
	b.openedAt = now
	b.consecutiveFailures++
	b.probeActive = false
}

// Reset forces the breaker closed and clears failure counts.
func (b *Breaker) Reset() {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := time.Now()
	b.state = Closed
	b.stateChangedAt = now
	b.openedAt = now
	b.consecutiveFailures = 0
	b.probeActive = false
}

// ConsecutiveFailures returns the current failure count.
func (b *Breaker) ConsecutiveFailures() int {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.consecutiveFailures
}

// TimeInStateMs returns milliseconds since the last state transition.
func (b *Breaker) TimeInStateMs() int64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	return time.Since(b.stateChangedAt).Milliseconds()
}

// ProbeActive returns whether a probe connection is currently active.
func (b *Breaker) ProbeActive() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.probeActive
}
EOF

