cat > internal/state/state.go <<'EOF'
package state

import (
    "net"
    "sync"
    "sync/atomic"
    "time"

    "meshrouter/internal/circuit"
    "meshrouter/internal/config"
    "meshrouter/internal/stats"
)

type HealthState string

const (
    Unknown   HealthState = "unknown"
    Healthy   HealthState = "healthy"
    Unhealthy HealthState = "unhealthy"
    Draining  HealthState = "draining"
)

type HealthEvent struct {
    Timestamp   time.Time
    Endpoint    string
    OldState    HealthState
    NewState    HealthState
    CheckResult string
}

type EndpointState struct {
    mu                  sync.Mutex
    Address             string
    Weight              int
    Config              config.Endpoint
    State               HealthState
    ActiveConnections  int
    Circuit            *circuit.Breaker
    Stats              *stats.Collector
    consecSuccess      int
    consecFailures     int
    drainDeadline      time.Time
    removed            bool
    connIDCounter      int64
    connections        map[int64]net.Conn
}

type ServiceState struct {
    mu                        sync.Mutex
    Name                      string
    ListenPort                int
    RoutingMode               string
    DrainTimeoutMs            int
    MaxConnectionsPerEndpoint int
    Endpoints                 []*EndpointState
    rrIndex                    int
    Listener                  net.Listener
    listenerStop              chan struct{}
    stopping                  bool
}

type State struct {
    mu         sync.RWMutex
    configPath string
    global     config.Global
    services   map[string]*ServiceState
    logMu      sync.Mutex
    healthLog  map[string][]HealthEvent
    reloadCh   chan struct{}
}

func NewState(cfg *config.Config, path string) *State {
    s := &State{
        configPath: path,
        services:   make(map[string]*ServiceState),
        healthLog:  make(map[string][]HealthEvent),
        reloadCh:   make(chan struct{}, 1),
    }
    s.applyConfigLocked(cfg)
    return s
}

func (s *State) ReloadChan() <-chan struct{} {
    return s.reloadCh
}

func (s *State) ConfigPath() string {
    s.mu.RLock()
    defer s.mu.RUnlock()
    return s.configPath
}

func (s *State) Global() config.Global {
    s.mu.RLock()
    defer s.mu.RUnlock()
    return s.global
}

func (s *State) ApplyConfig(cfg *config.Config) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.applyConfigLocked(cfg)
    select {
    case s.reloadCh <- struct{}{}:
    default:
    }
}

func (s *State) applyConfigLocked(cfg *config.Config) {
    s.global = cfg.Global
    seen := make(map[string]bool)
    for _, svc := range cfg.Services {
        seen[svc.Name] = true
        ss := s.services[svc.Name]
        if ss == nil {
            ss = newServiceState(svc)
            s.services[svc.Name] = ss
        } else {
            ss.mu.Lock()
            ss.Name = svc.Name
            ss.ListenPort = svc.ListenPort
            ss.RoutingMode = svc.RoutingMode
            ss.DrainTimeoutMs = svc.DrainTimeoutMs
            ss.MaxConnectionsPerEndpoint = svc.MaxConnectionsPerEndpoint
            ss.mu.Unlock()
            ss.applyEndpoints(svc.Endpoints, cfg.Global)
        }
    }
    for name, ss := range s.services {
        if !seen[name] {
            ss.mu.Lock()
            ss.stopping = true
            if ss.listenerStop != nil {
                close(ss.listenerStop)
                ss.listenerStop = nil
            }
            if ss.Listener != nil {
                ss.Listener.Close()
                ss.Listener = nil
            }
            ss.mu.Unlock()
            for _, ep := range ss.Endpoints {
                ep.StartDraining(ss.DrainTimeoutMs, true)
            }
        }
    }
}

func newServiceState(svc config.Service) *ServiceState {
    ss := &ServiceState{
        Name:                      svc.Name,
        ListenPort:                svc.ListenPort,
        RoutingMode:               svc.RoutingMode,
        DrainTimeoutMs:            svc.DrainTimeoutMs,
        MaxConnectionsPerEndpoint: svc.MaxConnectionsPerEndpoint,
        listenerStop:              nil,
    }
    for _, ep := range svc.Endpoints {
        ss.Endpoints = append(ss.Endpoints, newEndpointState(ep, stats.New(time.Duration(svc.DrainTimeoutMs)*time.Millisecond)))
    }
    return ss
}

func (ss *ServiceState) applyEndpoints(eps []config.Endpoint, global config.Global) {
    ss.mu.Lock()
    defer ss.mu.Unlock()
    seen := make(map[string]bool)
    for _, cep := range eps {
        seen[cep.Address] = true
        var ep *EndpointState
        for _, existing := range ss.Endpoints {
            if existing.Address == cep.Address {
                ep = existing
                break
            }
        }
        if ep == nil {
            ep = newEndpointState(cep, stats.New(time.Duration(global.StatsWindowSec)*time.Second))
            ss.Endpoints = append(ss.Endpoints, ep)
        } else {
            ep.mu.Lock()
            ep.Config = cep
            ep.Weight = cep.Weight
            ep.mu.Unlock()
        }
    }
    for _, ep := range ss.Endpoints {
        if !seen[ep.Address] {
            ep.StartDraining(ss.DrainTimeoutMs, true)
        }
    }
}

func newEndpointState(cep config.Endpoint, st *stats.Collector) *EndpointState {
    return &EndpointState{
        Address:      cep.Address,
        Weight:       cep.Weight,
        Config:       cep,
        State:        Unknown,
        Circuit:      circuit.New(time.Duration(5000) * time.Millisecond),
        Stats:        st,
        connections:  make(map[int64]net.Conn),
    }
}

func (s *State) GetService(name string) *ServiceState {
    s.mu.RLock()
    defer s.mu.RUnlock()
    return s.services[name]
}

func (s *State) Services() []*ServiceState {
    s.mu.RLock()
    defer s.mu.RUnlock()
    out := make([]*ServiceState, 0, len(s.services))
    for _, ss := range s.services {
        out = append(out, ss)
    }
    return out
}

func (s *State) GetEndpoint(service, address string) *EndpointState {
    ss := s.GetService(service)
    if ss == nil {
        return nil
    }
    ss.mu.Lock()
    defer ss.mu.Unlock()
    for _, ep := range ss.Endpoints {
        if ep.Address == address {
            return ep
        }
    }
    return nil
}

func (s *State) SetWeight(service, address string, weight int) error {
    ep := s.GetEndpoint(service, address)
    if ep == nil {
        return errNotFound("endpoint not found")
    }
    ep.mu.Lock()
    defer ep.mu.Unlock()
    if weight < 0 {
        weight = 0
    }
    ep.Weight = weight
    return nil
}

func (s *State) DrainEndpoint(service, address string) error {
    ss := s.GetService(service)
    if ss == nil {
        return errNotFound("service not found")
    }
    ep := s.GetEndpoint(service, address)
    if ep == nil {
        return errNotFound("endpoint not found")
    }
    ep.StartDraining(ss.DrainTimeoutMs, false)
    return nil
}

func (s *State) ResetCircuitBreaker(service, address string) error {
    ep := s.GetEndpoint(service, address)
    if ep == nil {
        return errNotFound("endpoint not found")
    }
    ep.Circuit.Reset()
    return nil
}

func (ep *EndpointState) StartDraining(timeoutMs int, markRemoved bool) {
    ep.mu.Lock()
    defer ep.mu.Unlock()
    ep.State = Draining
    ep.consecSuccess = 0
    ep.consecFailures = 0
    ep.drainDeadline = time.Now().Add(time.Duration(timeoutMs) * time.Millisecond)
    if markRemoved {
        ep.removed = true
    }
    if len(ep.connections) > 0 {
        go func(deadline time.Time, conns map[int64]net.Conn) {
            time.Sleep(time.Until(deadline))
            ep.closeConnectionsLocked()
        }(ep.drainDeadline, ep.connections)
    }
}

func (ep *EndpointState) AddConnection(conn net.Conn) int64 {
    ep.mu.Lock()
    defer ep.mu.Unlock()
    id := atomic.AddInt64(&ep.connIDCounter, 1)
    ep.connections[id] = conn
    ep.ActiveConnections++
    return id
}

func (ep *EndpointState) RemoveConnection(id int64) {
    ep.mu.Lock()
    defer ep.mu.Unlock()
    if _, ok := ep.connections[id]; ok {
        delete(ep.connections, id)
        if ep.ActiveConnections > 0 {
            ep.ActiveConnections--
        }
    }
}

func (ep *EndpointState) closeConnectionsLocked() {
    for id, c := range ep.connections {
        c.Close()
        delete(ep.connections, id)
    }
}

func (ep *EndpointState) Active() int {
    ep.mu.Lock()
    defer ep.mu.Unlock()
    return ep.ActiveConnections
}

func (ep *EndpointState) IsEligible(maxConns int) bool {
    ep.mu.Lock()
    defer ep.mu.Unlock()
    return ep.State == Healthy && ep.Circuit.IsClosed() && ep.Weight > 0 && ep.State != Draining && ep.ActiveConnections < maxConns
}

func (s *State) RecordHealthCheck(service, address string, success bool) HealthEvent {
    ss := s.GetService(service)
    if ss == nil {
        return HealthEvent{}
    }
    ep := s.GetEndpoint(service, address)
    if ep == nil {
        return HealthEvent{}
    }
    global := s.Global()
    ep.mu.Lock()
    oldState := ep.State
    result := "success"
    if !success {
        result = "failure"
    }
    if success {
        ep.consecSuccess++
        ep.consecFailures = 0
        if oldState == Unknown && ep.consecSuccess >= global.HealthyThreshold {
            ep.State = Healthy
        } else if oldState == Unhealthy && ep.consecSuccess >= global.HealthyThreshold {
            ep.State = Healthy
        }
    } else {
        ep.consecFailures++
        ep.consecSuccess = 0
        if (oldState == Healthy || oldState == Unknown) && ep.consecFailures >= global.UnhealthyThreshold {
            ep.State = Unhealthy
            ep.Circuit.Open()
            ep.consecFailures = 0
            timeout := time.Duration(ss.DrainTimeoutMs) * time.Millisecond
            go func(deadline time.Time) {
                time.Sleep(time.Until(deadline))
                ep.mu.Lock()
                ep.closeConnectionsLocked()
                ep.mu.Unlock()
            }(time.Now().Add(timeout))
        }
    }
    newState := ep.State
    ep.mu.Unlock()
    evt := HealthEvent{
        Timestamp:   time.Now(),
        Endpoint:    address,
        OldState:    oldState,
        NewState:    newState,
        CheckResult: result,
    }
    s.logMu.Lock()
    s.healthLog[service] = append(s.healthLog[service], evt)
    if len(s.healthLog[service]) > 1000 {
        s.healthLog[service] = s.healthLog[service][len(s.healthLog[service])-1000:]
    }
    s.logMu.Unlock()
    return evt
}

func (s *State) HealthLog(service string, lastN int) []HealthEvent {
    s.logMu.Lock()
    defer s.logMu.Unlock()
    events := s.healthLog[service]
    if lastN <= 0 || lastN > len(events) {
        lastN = len(events)
    }
    out := make([]HealthEvent, lastN)
    copy(out, events[len(events)-lastN:])
    return out
}

type notFoundError struct {
    msg string
}

func (e *notFoundError) Error() string {
    return e.msg
}

func errNotFound(msg string) error {
    return &notFoundError{msg: msg}
}
