)

type worker struct {
    cancel context.CancelFunc
    done   chan struct{}
}

type Monitor struct {
    state *state.State
    mu    sync.Mutex
    cur   *config.Config
    stop  chan struct{}
    workers map[string]*worker
}

func NewMonitor(s *state.State, cfg *config.Config) *Monitor {
    return &Monitor{
        state:   s,
        cur:     cfg,
        stop:    make(chan struct{}),
        workers: make(map[string]*worker),
    }
}

func (m *Monitor) Start() {
    m.mu.Lock()
    cfg := m.cur
    m.mu.Unlock()
    m.startWorkers(cfg)
}

func (m *Monitor) ApplyConfig(cfg *config.Config) {
    m.mu.Lock()
    m.cur = cfg
    m.mu.Unlock()
    m.stopWorkers()
    m.startWorkers(cfg)
}

func (m *Monitor) Stop() {
    close(m.stop)
    m.stopWorkers()
}

func (m *Monitor) startWorkers(cfg *config.Config) {
    for _, svc := range cfg.Services {
        for _, ep := range svc.Endpoints {
            key := svc.Name + "|" + ep.Address
            ctx, cancel := context.WithCancel(context.Background())
            w := &worker{cancel: cancel, done: make(chan struct{})}
            m.mu.Lock()
            m.workers[key] = w
            m.mu.Unlock()
            go m.run(ctx, cfg, svc.Name, ep, w.done)
        }
    }
}

func (m *Monitor) stopWorkers() {
    m.mu.Lock()
    workers := m.workers
    m.workers = make(map[string]*worker)
    m.mu.Unlock()
    for _, w := range workers {
        w.cancel()
        <-w.done
    }
}

func (m *Monitor) run(ctx context.Context, cfg *config.Config, service string, ep config.Endpoint, done chan struct{}) {
    defer close(done)
    interval := time.Duration(cfg.Global.HealthIntervalMs) * time.Millisecond
    if interval <= 0 {
        interval = 2 * time.Second
    }
    ticker := time.NewTicker(interval)
    defer ticker.Stop()
    for {
        select {
        case <-ctx.Done():
            return
        case <-m.stop:
            return
        case <-ticker.C:
        }
        success := checkEndpoint(ctx, ep)
        m.state.RecordHealthCheck(service, ep.Address, success)
        if ss := m.state.GetService(service); ss != nil {
            if eps := m.state.GetEndpoint(service, ep.Address); eps != nil {
                eps.Circuit.MaybeHalfOpen()
            }
            _ = ss
        }
    }
}

func checkEndpoint(ctx context.Context, ep config.Endpoint) bool {
    switch ep.HealthCheck {
    case "http":
        return checkHTTP(ctx, ep)
    case "exec":
        return checkExec(ctx, ep)
    default:
        return checkTCP(ep.Address)
    }
}

func checkTCP(address string) bool {
    conn, err := net.DialTimeout("tcp", address, time.Second)
    if err != nil {
        return false
    }
    conn.Close()
    return true
}

func checkHTTP(ctx context.Context, ep config.Endpoint) bool {
    path := ep.HealthPath
    if path == "" {
        path = "/"
    }
    url := fmt.Sprintf("http://%s%s", ep.Address, path)
    client := &http.Client{Timeout: 2 * time.Second}
    req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
    if err != nil {
        return false
    }
    resp, err := client.Do(req)
    if err != nil {
        return false
    }
    defer resp.Body.Close()
    if resp.StatusCode != 200 {
        return false
    }
    body, err := io.ReadAll(resp.Body)
    if err != nil {
        return false
    }
    return strings.Contains(strings.ToLower(string(body)), "ok")
}

func checkExec(ctx context.Context, ep config.Endpoint) bool {
    if ep.HealthCmd == "" {
        return false
    }
    c := exec.CommandContext(ctx, "sh", "-c", ep.HealthCmd)
    c.Stdout = io.Discard
    c.Stderr = io.Discard
    if err := c.Start(); err != nil {
        return false
    }
    done := make(chan error, 1)
    go func() {
        done <- c.Wait()
    }()
    select {
    case <-time.After(3 * time.Second):
        c.Process.Kill()
        <-done
        return false
    case err := <-done:
        return err == nil
    }
}
