package state

import (
    "sort"
    "time"
)

// SelectResult contains selected endpoint and whether it is a half-open probe.
type SelectResult struct {
    Endpoint *EndpointState
    Probe    bool
}

// SelectEndpoint chooses an endpoint for the next connection.
func (s *State) SelectEndpoint(service string) (SelectResult, error) {
    ss := s.GetService(service)
    if ss == nil {
        return SelectResult{}, errNotFound("service not found")
    }
    ss.mu.Lock()
    maxConns := ss.MaxConnectionsPerEndpoint
    mode := ss.RoutingMode
    endpoints := make([]*EndpointState, len(ss.Endpoints))
    copy(endpoints, ss.Endpoints)
    ss.mu.Unlock()

    now := time.Now()
    _ = now

    var regular []*EndpointState
    for _, ep := range endpoints {
        ep.mu.Lock()
        eligible := ep.State == Healthy && ep.Circuit.IsClosed() && ep.Weight > 0 && ep.State != Draining && ep.ActiveConnections < maxConns
        if eligible {
            regular = append(regular, ep)
        }
        ep.mu.Unlock()
    }

    if len(regular) > 0 {
        if mode == "least-connections" {
            return SelectResult{Endpoint: selectLeastConnections(regular, maxConns), Probe: false}, nil
        }
        return SelectResult{Endpoint: selectWeighted(regular), Probe: false}, nil
    }

    for _, ep := range endpoints {
        ep.mu.Lock()
        halfOpen := ep.State == Healthy && ep.Circuit.IsHalfOpen() && ep.Weight > 0 && ep.State != Draining && ep.ActiveConnections < maxConns
        ep.mu.Unlock()
        if halfOpen && ep.Circuit.AcquireProbe() {
            return SelectResult{Endpoint: ep, Probe: true}, nil
        }
    }
    return SelectResult{}, errNotFound("no eligible endpoints")
}

func selectWeighted(eps []*EndpointState) *EndpointState {
    var best *EndpointState
    var bestWeight int
    var totalWeight int
    for _, ep := range eps {
        ep.mu.Lock()
        ep.currentWeight += ep.Weight
        totalWeight += ep.Weight
        cw := ep.currentWeight
        w := ep.Weight
        ep.mu.Unlock()
        if best == nil || cw > bestWeight {
            best = ep
            bestWeight = cw
        }
        _ = w
    }
    if best != nil {
        best.mu.Lock()
        best.currentWeight -= totalWeight
        best.mu.Unlock()
    }
    return best
}

func selectLeastConnections(eps []*EndpointState, maxConns int) *EndpointState {
    sort.SliceStable(eps, func(i, j int) bool {
        ai := eps[i].Active()
        aj := eps[j].Active()
        if ai != aj {
            return ai < aj
        }
        return eps[i].Address < eps[j].Address
    })
    return eps[0]
}
