type EndpointView struct {
    Address            string `json:"address"`
    State              string `json:"state"`
    Weight             int    `json:"weight"`
    ActiveConnections int    `json:"active_connections"`
    CircuitState       string `json:"circuit_state"`
}

type ServiceView struct {
    Name        string         `json:"name"`
    ListenPort  int            `json:"listen_port"`
    RoutingMode string         `json:"routing_mode"`
    Endpoints   []EndpointView `json:"endpoints"`
}

func (s *State) ServiceView(name string) (ServiceView, bool) {
    ss := s.GetService(name)
    if ss == nil {
        return ServiceView{}, false
    }
    return ss.View(), true
}

func (s *State) ServicesView() []ServiceView {
    services := s.Services()
    out := make([]ServiceView, 0, len(services))
    for _, ss := range services {
        out = append(out, ss.View())
    }
    sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
    return out
}

func (ss *ServiceState) View() ServiceView {
    ss.mu.Lock()
    defer ss.mu.Unlock()
    sv := ServiceView{
        Name:        ss.Name,
        ListenPort:  ss.ListenPort,
        RoutingMode: ss.RoutingMode,
        Endpoints:   make([]EndpointView, 0, len(ss.Endpoints)),
    }
    for _, ep := range ss.Endpoints {
        ep.mu.Lock()
        sv.Endpoints = append(sv.Endpoints, EndpointView{
            Address:            ep.Address,
            State:              string(ep.State),
            Weight:             ep.Weight,
            ActiveConnections: ep.ActiveConnections,
            CircuitState:       string(ep.Circuit.State()),
        })
        ep.mu.Unlock()
    }
    return sv
}

type StatsEndpointView struct {
    Address string `json:"address"`
    stats.Snapshot
}

type StatsView struct {
    Service   string              `json:"service"`
    WindowSec int                 `json:"window_sec"`
    Endpoints []StatsEndpointView `json:"endpoints"`
}

func (s *State) StatsView(name string, windowSec int) (StatsView, bool) {
    ss := s.GetService(name)
    if ss == nil {
        return StatsView{}, false
    }
    sv := StatsView{
        Service:   name,
        WindowSec: windowSec,
        Endpoints: make([]StatsEndpointView, 0),
    }
    ss.mu.Lock()
    for _, ep := range ss.Endpoints {
        ep.mu.Lock()
        sv.Endpoints = append(sv.Endpoints, StatsEndpointView{
            Address:  ep.Address,
            Snapshot: ep.Stats.Snapshot(ep.ActiveConnections),
        })
        ep.mu.Unlock()
    }
    ss.mu.Unlock()
    return sv, true
}

type HealthEventView struct {
    Timestamp   time.Time `json:"timestamp"`
    Endpoint    string    `json:"endpoint"`
    OldState    string    `json:"old_state"`
    NewState    string    `json:"new_state"`
    CheckResult string    `json:"check_result"`
}

func (s *State) HealthLogView(name string, lastN int) []HealthEventView {
    events := s.HealthLog(name, lastN)
    out := make([]HealthEventView, 0, len(events))
    for _, e := range events {
        out = append(out, HealthEventView{
            Timestamp:   e.Timestamp,
            Endpoint:    e.Endpoint,
            OldState:    string(e.OldState),
            NewState:    string(e.NewState),
            CheckResult: e.CheckResult,
        })
    }
    return out
}

type CircuitView struct {
    Address             string `json:"address"`
    CircuitState        string `json:"circuit_state"`
    ConsecutiveFailures int    `json:"consecutive_failures"`
    TimeInStateMs      int64  `json:"time_in_state_ms"`
    ProbeActive        bool   `json:"probe_active"`
}

func (s *State) CircuitsView(name string) ([]CircuitView, bool) {
    ss := s.GetService(name)
    if ss == nil {
        return nil, false
    }
    ss.mu.Lock()
    out := make([]CircuitView, 0, len(ss.Endpoints))
    for _, ep := range ss.Endpoints {
        ep.mu.Lock()
        out = append(out, CircuitView{
            Address:             ep.Address,
            CircuitState:        string(ep.Circuit.State()),
            ConsecutiveFailures: ep.Circuit.ConsecutiveFailures(),
            TimeInStateMs:      ep.Circuit.TimeInStateMs(),
            ProbeActive:        ep.Circuit.ProbeActive(),
        })
        ep.mu.Unlock()
    }
    ss.mu.Unlock()
    return out, true
}

func (s *State) ResolveEndpoint(service string) (string, error) {
    ss := s.GetService(service)
    if ss == nil {
        return "", errNotFound("service not found")
    }
    ss.mu.Lock()
    maxConns := ss.MaxConnectionsPerEndpoint
    mode := ss.RoutingMode
    endpoints := make([]*EndpointState, len(ss.Endpoints))
    copy(endpoints, ss.Endpoints)
    ss.mu.Unlock()

    var regular []*EndpointState
    for _, ep := range endpoints {
        if ep.IsEligible(maxConns) {
            regular = append(regular, ep)
        }
    }

    if len(regular) > 0 {
        if mode == "least-connections" {
            ep := selectLeastConnections(regular, maxConns)
            return ep.Address, nil
        }
        var best *EndpointState
        var bestWeight int
        for _, ep := range regular {
            ep.mu.Lock()
            cw := ep.currentWeight + ep.Weight
            ep.mu.Unlock()
            if best == nil || cw > bestWeight {
                best = ep
                bestWeight = cw
            }
        }
        if best != nil {
            return best.Address, nil
        }
    }

    for _, ep := range endpoints {
        ep.mu.Lock()
        halfOpen := ep.State == Healthy && ep.Circuit.IsHalfOpen() && ep.Weight > 0 && ep.State != Draining && ep.ActiveConnections < maxConns && !ep.Circuit.ProbeActive()
        ep.mu.Unlock()
        if halfOpen {
            return ep.Address, nil
        }
    }
    return "", errNotFound("no eligible endpoints")
}
