func (ep *EndpointState) TryAddConnection(conn net.Conn, maxConns int) (int64, bool) {
    ep.mu.Lock()
    defer ep.mu.Unlock()
    if ep.ActiveConnections >= maxConns {
        return 0, false
    }
    id := atomic.AddInt64(&ep.connIDCounter, 1)
    ep.connections[id] = conn
    ep.ActiveConnections++
