    mu        sync.Mutex
    listeners map[string]*serviceListener
}

func NewRouter(s *state.State) *Router {
    return &Router{
        state:     s,
        listeners: make(map[string]*serviceListener),
    }
}

func (r *Router) Start() {
    for _, ss := range r.state.Services() {
        if !ss.IsStopping() {
            r.startService(ss)
        }
    }
}

func (r *Router) Reload() {
    services := r.state.Services()
    seen := make(map[string]bool)
    for _, ss := range services {
        seen[ss.Name] = true
        r.mu.Lock()
        sl, ok := r.listeners[ss.Name]
        r.mu.Unlock()
        if !ok {
            if !ss.IsStopping() {
                r.startService(ss)
            }
            continue
        }
        if sl.port != ss.ListenPort {
            r.stopService(ss.Name, true)
            r.startService(ss)
        }
    }
    r.mu.Lock()
    for name := range r.listeners {
        if !seen[name] {
            r.mu.Unlock()
            r.stopService(name, true)
            r.mu.Lock()
        }
    }
    r.mu.Unlock()
}

func (r *Router) startService(ss *state.ServiceState) {
    addr := ":" + intToStr(ss.ListenPort)
    ln, err := net.Listen("tcp", addr)
    if err != nil {
        log.Printf("router: listen %s on %s failed: %v", ss.Name, addr, err)
        return
    }
    sl := &serviceListener{
        service:  ss.Name,
        port:     ss.ListenPort,
        listener: ln,
        stop:     make(chan struct{}),
        done:     make(chan struct{}),
    }
    r.mu.Lock()
    r.listeners[ss.Name] = sl
    r.mu.Unlock()
    go sl.acceptLoop(r)
}

func (r *Router) stopService(name string, drain bool) {
    r.mu.Lock()
    sl, ok := r.listeners[name]
    if ok {
        delete(r.listeners, name)
    }
    r.mu.Unlock()
    if !ok {
        return
    }
    sl.stopAccept(drain, r)
}

func (r *Router) Stop() {
    r.mu.Lock()
    listeners := r.listeners
    r.listeners = make(map[string]*serviceListener)
    r.mu.Unlock()
    var wg sync.WaitGroup
    for name, sl := range listeners {
        wg.Add(1)
        go func(name string, sl *serviceListener) {
            defer wg.Done()
            sl.stopAccept(true, r)
        }(name, sl)
    }
    wg.Wait()
}

func (sl *serviceListener) acceptLoop(r *Router) {
    defer close(sl.done)
    for {
        conn, err := sl.listener.Accept()
        if err != nil {
            return
        }
        sl.wg.Add(1)
        go func(c net.Conn) {
            defer sl.wg.Done()
            r.handleConn(sl.service, c)
        }(conn)
    }
}

func (sl *serviceListener) stopAccept(drain bool, r *Router) {
    select {
    case <-sl.stop:
    default:
        close(sl.stop)
    }
    sl.listener.Close()
    <-sl.done
    if drain {
        ss := r.state.GetService(sl.service)
        timeout := 5 * time.Second
        if ss != nil {
            timeout = time.Duration(ss.DrainTimeoutMs) * time.Millisecond
            if timeout <= 0 {
                timeout = 5 * time.Second
            }
        }
        done := make(chan struct{})
        go func() {
            sl.wg.Wait()
            close(done)
        }()
        select {
        case <-done:
        case <-time.After(timeout):
            r.state.CloseServiceConnections(sl.service)
            <-done
        }
    } else {
        sl.wg.Wait()
    }
}

func (r *Router) handleConn(service string, client net.Conn) {
    start := time.Now()
    res, err := r.state.SelectEndpoint(service)
    if err != nil {
        if cand, cerr := r.state.SelectCandidate(service); cerr == nil {
            ss := r.state.GetService(service)
            if ss != nil && cand.Active() >= ss.MaxConnectionsPerEndpoint {
                cand.Stats.RecordRejection()
            }
        }
        client.Close()
        return
    }
    ep := res.Endpoint

    var id int64
    if !res.Probe {
        var ok bool
        id, ok = ep.TryAddConnection(client, res.MaxConns)
        if !ok {
            ep.Stats.RecordRejection()
            client.Close()
            return
        }
    }

    backend, err := net.Dial("tcp", ep.Address)
    if err != nil {
        if id != 0 {
            ep.RemoveConnection(id)
        }
        ep.Stats.RecordConnection(0, 0, time.Since(start), true)
        if res.Probe {
            ep.Circuit.ProbeFailure()
        }
        client.Close()
        return
    }

    if res.Probe {
        ep.Circuit.ProbeSuccess()
        var ok bool
        id, ok = ep.TryAddConnection(client, res.MaxConns)
        if !ok {
            ep.Stats.RecordRejection()
            backend.Close()
            client.Close()
            return
        }
    }

    bytesIn, bytesOut := forward(client, backend)
    backend.Close()
    client.Close()
    ep.RemoveConnection(id)
    ep.Stats.RecordConnection(bytesIn, bytesOut, time.Since(start), false)
}

func forward(client, backend net.Conn) (int64, int64) {
    var bytesIn, bytesOut int64
    var wg sync.WaitGroup
    wg.Add(2)
    go func() {
        defer wg.Done()
        n, _ := io.Copy(backend, client)
        bytesOut = n
        backend.Close()
        client.Close()
    }()
    go func() {
        defer wg.Done()
        n, _ := io.Copy(client, backend)
        bytesIn = n
        client.Close()
        backend.Close()
    }()
    wg.Wait()
    return bytesIn, bytesOut
}

func intToStr(i int) string {
    if i == 0 {
        return "0"
    }
    var buf [12]byte
    pos := len(buf)
    neg := false
    if i < 0 {
        neg = true
        i = -i
    }
    for i > 0 {
        pos--
        buf[pos] = byte('0' + i%10)
        i /= 10
    }
    if neg {
        pos--
        buf[pos] = '-'
    }
    return string(buf[pos:])
}
