        }
        if err := json.Unmarshal(req.Args, &args); err != nil {
            return nil, err
        }
        return s.state.HealthLogView(args.Name, args.LastN), nil
    case "get_circuit_breakers":
        var args struct {
            Name string `json:"name"`
        }
        if err := json.Unmarshal(req.Args, &args); err != nil {
            return nil, err
        }
        cv, ok := s.state.CircuitsView(args.Name)
        if !ok {
            return nil, errors.New("service not found")
        }
        return cv, nil
    case "reset_circuit_breaker":
        var args struct {
            Name    string `json:"name"`
            Address string `json:"address"`
        }
        if err := json.Unmarshal(req.Args, &args); err != nil {
            return nil, err
        }
        if err := s.state.ResetCircuitBreaker(args.Name, args.Address); err != nil {
            return nil, err
        }
        return "OK", nil
    case "reload_config":
        path := s.state.ConfigPath()
        cfg, err := config.Load(path)
        if err != nil {
            return nil, err
        }
        s.state.ApplyConfig(cfg)
        return "OK", nil
    default:
        return nil, fmt.Errorf("unknown command: %s", req.Cmd)
    }
}

func init() {
    _ = strconv.Itoa(0)
}
