type request struct {
    Cmd  string          `json:"cmd"`
    Args json.RawMessage `json:"args"`
}

type response struct {
    Status string          `json:"status"`
    Data   json.RawMessage `json:"data"`
}

func main() {
    if len(os.Args) < 2 {
        fmt.Fprintln(os.Stderr, "usage: meshctl <command> [args]")
        os.Exit(1)
    }
    cmd := os.Args[1]
    args := map[string]interface{}{}
    switch cmd {
    case "status":
    case "stats":
        if len(os.Args) < 3 {
            fmt.Fprintln(os.Stderr, "usage: meshctl stats <service>")
            os.Exit(1)
        }
        args["name"] = os.Args[2]
    case "set-weight":
        if len(os.Args) < 5 {
            fmt.Fprintln(os.Stderr, "usage: meshctl set-weight <service> <endpoint> <weight>")
            os.Exit(1)
        }
        w, err := strconv.Atoi(os.Args[4])
        if err != nil {
            fmt.Fprintf(os.Stderr, "invalid weight: %v\n", err)
            os.Exit(1)
        }
        args["name"] = os.Args[2]
        args["address"] = os.Args[3]
        args["weight"] = w
    case "drain":
        if len(os.Args) < 4 {
            fmt.Fprintln(os.Stderr, "usage: meshctl drain <service> <endpoint>")
            os.Exit(1)
        }
        args["name"] = os.Args[2]
        args["address"] = os.Args[3]
    case "health-log":
        if len(os.Args) < 3 {
            fmt.Fprintln(os.Stderr, "usage: meshctl health-log <service> [--last N]")
            os.Exit(1)
        }
        args["name"] = os.Args[2]
        n := 20
        for _, a := range os.Args[3:] {
            if strings.HasPrefix(a, "--last") && len(a) > 6 {
                v, err := strconv.Atoi(a[6:])
                if err == nil {
                    n = v
                }
            }
        }
        args["last_n"] = n
    case "resolve":
        if len(os.Args) < 3 {
            fmt.Fprintln(os.Stderr, "usage: meshctl resolve <service>")
            os.Exit(1)
        }
        args["name"] = os.Args[2]
    case "circuits":
        if len(os.Args) < 3 {
            fmt.Fprintln(os.Stderr, "usage: meshctl circuits <service>")
            os.Exit(1)
        }
        args["name"] = os.Args[2]
    case "reset-circuit":
        if len(os.Args) < 4 {
            fmt.Fprintln(os.Stderr, "usage: meshctl reset-circuit <service> <endpoint>")
            os.Exit(1)
        }
        args["name"] = os.Args[2]
        args["address"] = os.Args[3]
    case "reload":
    default:
        fmt.Fprintf(os.Stderr, "unknown command: %s\n", cmd)
        os.Exit(1)
    }
    data, err := sendCommand(cmd, args)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
    fmt.Println(data)
}

func sendCommand(cmd string, args map[string]interface{}) (string, error) {
    var rawArgs json.RawMessage
    if args != nil {
        b, err := json.Marshal(args)
        if err != nil {
            return "", err
        }
        rawArgs = b
    } else {
        rawArgs = json.RawMessage("{}")
    }
    req := request{Cmd: cmd, Args: rawArgs}
    reqBytes, err := json.Marshal(req)
    if err != nil {
        return "", err
    }
    conn, err := net.Dial("unix", "/tmp/meshd.sock")
    if err != nil {
        return "", fmt.Errorf("connect to meshd failed: %w", err)
    }
    defer conn.Close()
    fmt.Fprintf(conn, "%s\n", string(reqBytes))
    reader := bufio.NewReader(conn)
    line, err := reader.ReadString('\n')
    if err != nil {
        return "", err
    }
    line = strings.TrimRight(line, "\r\n")
    var resp response
    if err := json.Unmarshal([]byte(line), &resp); err != nil {
        return "", err
    }
    if resp.Status != "ok" {
        var msg string
        if err := json.Unmarshal(resp.Data, &msg); err == nil {
            return "", fmt.Errorf("%s", msg)
        }
        return "", fmt.Errorf("%s", string(resp.Data))
    }
    return prettyData(cmd, resp.Data)
}

func prettyData(cmd string, data json.RawMessage) (string, error) {
    switch cmd {
    case "status":
        var services []struct {
            Name        string `json:"name"`
            ListenPort  int    `json:"listen_port"`
            RoutingMode string `json:"routing_mode"`
            Endpoints   []struct {
                Address            string `json:"address"`
                State             string `json:"state"`
                Weight            int    `json:"weight"`
                ActiveConnections int    `json:"active_connections"`
                CircuitState       string `json:"circuit_state"`
            } `json:"endpoints"`
        }
        if err := json.Unmarshal(data, &services); err != nil {
            return "", err
        }
        var b strings.Builder
        fmt.Fprintf(&b, "%-14s %-18s %-10s %-7s %-11s %-7s\n", "SERVICE", "ENDPOINT", "STATE", "WEIGHT", "CIRCUIT", "ACTIVE")
        for _, svc := range services {
            for _, ep := range svc.Endpoints {
                fmt.Fprintf(&b, "%-14s %-18s %-10s %-7d %-11s %-7d\n", svc.Name, ep.Address, ep.State, ep.Weight, ep.CircuitState, ep.ActiveConnections)
            }
        }
        return strings.TrimRight(b.String(), "\n"), nil
    case "resolve":
        var addr string
        if err := json.Unmarshal(data, &addr); err != nil {
            return "", err
        }
        return addr, nil
    case "set-weight", "drain", "reset-circuit", "reload":
        var s string
        if err := json.Unmarshal(data, &s); err != nil {
            return "", err
        }
        return s, nil
    default:
        var v interface{}
        if err := json.Unmarshal(data, &v); err != nil {
            return "", err
        }
        b, err := json.MarshalIndent(v, "", "  ")
        if err != nil {
            return "", err
        }
        return string(b), nil
    }
}
